//! A G-code job: the lines to stream plus a time estimate per line, so the
//! Job card can show progress, the current layer and an ETA for any file.

use std::sync::Arc;

/// Something that can be wound: generated by the designer or loaded from disk.
pub struct JobSource {
    pub name: String,
    pub lines: Arc<Vec<String>>,
    pub estimate: Arc<JobEstimate>,
    /// Came from the Wind Designer (so it can go out of date).
    pub from_designer: bool,
}

impl JobSource {
    pub fn new(name: String, lines: Arc<Vec<String>>, from_designer: bool) -> Self {
        let estimate = Arc::new(estimate(&lines));
        Self {
            name,
            lines,
            estimate,
            from_designer,
        }
    }

    pub fn load(path: &std::path::Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|e| format!("Could not open {}: {e}", path.display()))?;
        let lines: Vec<String> = text.lines().map(str::to_owned).collect();
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_else(|| "file.gcode".into());
        Ok(Self::new(name, Arc::new(lines), false))
    }
}

pub struct JobEstimate {
    /// Estimated seconds from the start until line `i` has run.
    pub cumulative_s: Vec<f32>,
    pub total_s: f64,
    /// (line index, text) for each `; Layer N of M: type` comment.
    pub layers: Vec<(usize, String)>,
}

impl JobEstimate {
    /// Estimated seconds of work done once the first `done` lines have run.
    pub fn elapsed_at(&self, done: usize) -> f64 {
        match done {
            0 => 0.0,
            d => self.cumulative_s[(d - 1).min(self.cumulative_s.len() - 1)] as f64,
        }
    }

    /// The layer label in effect once `done` lines have run, e.g. "2 of 5: helical".
    pub fn layer_at(&self, done: usize) -> Option<&str> {
        self.layers
            .iter()
            .take_while(|(i, _)| *i < done.max(1))
            .last()
            .map(|(_, s)| s.as_str())
    }
}

/// Time each move the way cyclone does: distance in Marlin units (mm, with
/// degrees treated as mm) over the feed rate, assuming instant acceleration.
pub fn estimate(lines: &[String]) -> JobEstimate {
    let mut pos = [0.0_f64; 3];
    let mut feed = 0.0_f64;
    let mut total = 0.0_f64;
    let mut cumulative_s = Vec::with_capacity(lines.len());
    let mut layers = Vec::new();

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();
        if let Some(comment) = trimmed.strip_prefix(';')
            && let Some(rest) = comment.trim().strip_prefix("Layer ") {
                layers.push((i, rest.to_string()));
            }
        let code = trimmed.split(';').next().unwrap_or("").trim();
        if !code.is_empty() {
            let mut words = code.split_whitespace();
            let cmd = words.next().unwrap_or("");
            let mut target = pos;
            let mut new_feed = None;
            for w in words {
                let (axis, value) = w.split_at(1);
                let Ok(v) = value.parse::<f64>() else { continue };
                match axis {
                    "X" | "x" => target[0] = v,
                    "Y" | "y" => target[1] = v,
                    "Z" | "z" => target[2] = v,
                    "F" | "f" => new_feed = Some(v),
                    _ => {}
                }
            }
            match cmd {
                "G0" | "G1" | "G00" | "G01" => {
                    if let Some(f) = new_feed {
                        feed = f;
                    }
                    let dist = ((target[0] - pos[0]).powi(2)
                        + (target[1] - pos[1]).powi(2)
                        + (target[2] - pos[2]).powi(2))
                    .sqrt();
                    if dist > 0.0 && feed > 0.0 {
                        total += dist / feed * 60.0;
                    }
                    pos = target;
                }
                "G92" => pos = target,
                _ => {}
            }
        }
        cumulative_s.push(total as f32);
    }

    JobEstimate {
        cumulative_s,
        total_s: total,
        layers,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lines(text: &str) -> Vec<String> {
        text.replace("\r\n", "\n").lines().map(str::to_owned).collect()
    }

    /// Our estimate from the G-code text matches cyclone's own profiler.
    #[test]
    fn matches_cyclone_time_estimate() {
        for (gcode, log) in [
            (include_str!("../tests/fixtures/helical.gcode"), include_str!("../tests/fixtures/helical.log")),
            (include_str!("../tests/fixtures/mixed.gcode"), include_str!("../tests/fixtures/mixed.log")),
        ] {
            let est = estimate(&lines(gcode));
            let cyclone: f64 = log
                .lines()
                .find_map(|l| l.strip_prefix("Total time estimate: "))
                .and_then(|r| r.split_whitespace().next())
                .and_then(|n| n.parse().ok())
                .expect("total in log");
            let rel = (est.total_s - cyclone).abs() / cyclone;
            assert!(rel < 1e-6, "ours {} vs cyclone {cyclone}", est.total_s);
        }
    }

    #[test]
    fn loads_a_gcode_file() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/hoop.gcode");
        let src = JobSource::load(&path).unwrap();
        assert_eq!(src.name, "hoop.gcode");
        assert!(!src.from_designer);
        assert_eq!(src.lines.len(), 379);
        assert!(src.estimate.total_s > 0.0);
        assert!(JobSource::load(std::path::Path::new("no/such/file.gcode")).is_err());
    }

    #[test]
    fn layers_and_progress() {
        let l = lines(include_str!("../tests/fixtures/mixed.gcode"));
        let est = estimate(&l);
        assert_eq!(est.layers.len(), 5);
        assert_eq!(est.layers[1].1, "2 of 6: helical");
        assert_eq!(est.layer_at(0), None);
        assert_eq!(est.layer_at(l.len()), Some("5 of 6: hoop"));
        assert_eq!(est.elapsed_at(l.len()), est.cumulative_s[l.len() - 1] as f64);
    }
}
